// Middleware kiểm tra sức khỏe của chính Gateway
app.MapGet("/gateway-health", () => Results.Ok(new { Status = "Healthy", Gateway = "YARP", Time = DateTime.UtcNow }));

// Kích hoạt pipeline của Reverse Proxy
app.MapReverseProxy(proxyPipeline =>
{
    // Có thể chèn middleware kiểm tra logic nghiệp vụ tại đây
    proxyPipeline.Use((context, next) =>
    {
        // Đo thời gian chuyển tiếp
        var start = Stopwatch.GetTimestamp();
        return next().ContinueWith(t =>
        {
            var elapsedMs = Stopwatch.GetElapsedTime(start).TotalMilliseconds;
            context.Response.Headers.Append("X-Proxy-Latency-Ms", elapsedMs.ToString("F2"));
            return t;
        }, TaskScheduler.Default).Unwrap();
    });
});

