public async Task<ProductDto?> GetProductByIdAsync(int productId, CancellationToken ct = default)
{
    string cacheKey = $"product:{productId}";

    // 1. Kiểm tra Cache trước
    var cachedData = await _redisDb.StringGetAsync(cacheKey);
    if (!cachedData.IsNullOrEmpty)
    {
        // Cache Hit: Deserialize và trả về ngay (0.5ms)
        return JsonSerializer.Deserialize<ProductDto>(cachedData!);
    }

    // 2. Cache Miss: Đọc dữ liệu từ Database chính (5-20ms)
    var product = await _dbContext.Products
        .AsNoTracking()
        .FirstOrDefaultAsync(p => p.Id == productId, ct);

    if (product != null)
    {
        var dto = new ProductDto(product.Id, product.Name, product.Price, product.Description);

        // 3. Tự ghi dữ liệu vào Cache kèm TTL 10 phút (Lazy Loading)
        await _redisDb.StringSetAsync(
            cacheKey, 
            JsonSerializer.Serialize(dto), 
            TimeSpan.FromMinutes(10));

        return dto;
    }

    return null;
}

public static class CacheTtlPolicy
{
    // Dữ liệu tĩnh, hiếm khi đổi: Cache dài hạn
    public static readonly TimeSpan ProductCatalog = TimeSpan.FromHours(12);

    // Dữ liệu cập nhật thường xuyên: Cache trung hạn
    public static readonly TimeSpan ProductPrice = TimeSpan.FromMinutes(10);

    // Dữ liệu nhạy cảm biến động liên tục: Cache cực ngắn kèm cơ chế Invalidate
    public static readonly TimeSpan FlashSaleInventory = TimeSpan.FromSeconds(5);
}

public async Task UpdateProductPriceAsync(int productId, decimal newPrice)
{
    // Bước 1: Cập nhật Database trước (Source of Truth)
    var product = await _dbContext.Products.FindAsync(productId);
    if (product == null) throw new NotFoundException();

    product.Price = newPrice;
    await _dbContext.SaveChangesAsync(); // Transaction commit xong an toàn

    // Bước 2: XÓA Key trên Cache (Không update, chỉ delete!)
    string cacheKey = $"product:{productId}";
    await _redisDb.KeyDeleteAsync(cacheKey);

    // Lần đọc kế tiếp của khách hàng sẽ tự động lấy giá mới từ DB và nạp lại Cache.
}

public async Task<string?> GetProductWithLockAsync(string productId)
{
    string cacheKey = $"product:{productId}";
    string lockKey = $"lock:{cacheKey}";

    var data = await _redisDb.StringGetAsync(cacheKey);
    if (!data.IsNullOrEmpty) return data;

    // Chỉ 1 luồng được cấp Lock trong 5 giây (tránh Stampede)
    bool isLockAcquired = await _redisDb.StringSetAsync(lockKey, "1", TimeSpan.FromSeconds(5), When.NotExists);

    if (isLockAcquired)
    {
        try
        {
            // Luồng duy nhất truy vấn Database
            var dbData = await FetchFromDatabaseAsync(productId);
            await _redisDb.StringSetAsync(cacheKey, dbData, TimeSpan.FromMinutes(10));
            return dbData;
        }
        finally
        {
            await _redisDb.KeyDeleteAsync(lockKey);
        }
    }
    else
    {
        // Các luồng khác chờ 50ms rồi đọc lại Cache
        await Task.Delay(50);
        return await _redisDb.StringGetAsync(cacheKey);
    }
}

public static TimeSpan GetJitteredTtl(TimeSpan baseTtl, double jitterPercentage = 0.1)
{
    // Ví dụ baseTtl = 60 phút, jitterPercentage = 10% (từ -6 phút đến +6 phút)
    double maxJitterSeconds = baseTtl.TotalSeconds * jitterPercentage;
    double randomJitter = (Random.Shared.NextDouble() * 2 - 1) * maxJitterSeconds;

    return TimeSpan.FromSeconds(baseTtl.TotalSeconds + randomJitter);
}

