public class CacheWarmerHostedService : IHostedService
{
    private readonly IServiceProvider _serviceProvider;
    public CacheWarmerHostedService(IServiceProvider serviceProvider) => _serviceProvider = serviceProvider;

    public async Task StartAsync(CancellationToken cancellationToken)
    {
        using var scope = _serviceProvider.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();
        var redis = scope.ServiceProvider.GetRequiredService<IConnectionMultiplexer>().GetDatabase();

        // Nạp trước Top 1.000 sản phẩm được xem nhiều nhất vào Cache
        var topProducts = await db.Products
            .OrderByDescending(p => p.ViewCount)
            .Take(1000)
            .ToListAsync(cancellationToken);

        foreach (var p in topProducts)
        {
            await redis.StringSetAsync($"product:{p.Id}", JsonSerializer.Serialize(p), TimeSpan.FromHours(6));
        }

        Console.WriteLine($"Đã làm ấm thành công {topProducts.Count} sản phẩm vào Cache!");
    }

    public Task StopAsync(CancellationToken cancellationToken) => Task.CompletedTask;
}

