// 1. DTO VÀ HÀM ENCODE / DECODE CURSOR TOKEN
public record CursorPayload(int LastId, DateTime LastCreatedAt);

public static class CursorHelper
{
    public static string Encode(int id, DateTime createdAt)
    {
        var json = JsonSerializer.Serialize(new CursorPayload(id, createdAt));
        return Convert.ToBase64String(Encoding.UTF8.GetBytes(json));
    }

    public static CursorPayload? Decode(string? cursor)
    {
        if (string.IsNullOrWhiteSpace(cursor)) return null;
        try {
            var json = Encoding.UTF8.GetString(Convert.FromBase64String(cursor));
            return JsonSerializer.Deserialize<CursorPayload>(json);
        } catch { return null; }
    }
}

// 2. ENDPOINT API XỬ LÝ (SỬ DỤNG EF CORE / LINQ)
app.MapGet("/api/v1/orders", async (string? cursor, int limit = 3, AppDbContext db) =>
{
    var cursorData = CursorHelper.Decode(cursor);

    // Mẹo Limit + 1 để kiểm tra hasNextPage mà không cần COUNT(*)
    var query = db.Orders.AsNoTracking();
    if (cursorData != null)
    {
        // Seek trực tiếp trên Composite Index (CreatedAt DESC, Id DESC)
        query = query.Where(o => o.CreatedAt < cursorData.LastCreatedAt 
                              || (o.CreatedAt == cursorData.LastCreatedAt && o.Id < cursorData.LastId));
    }

    var items = await query
        .OrderByDescending(o => o.CreatedAt)
        .ThenByDescending(o => o.Id)
        .Take(limit + 1)
        .ToListAsync();

    bool hasNextPage = items.Count > limit;
    if (hasNextPage) items.RemoveAt(limit); // Loại bỏ phần tử kiểm tra thứ 4

    var lastItem = items.LastOrDefault();
    string? endCursor = lastItem != null ? CursorHelper.Encode(lastItem.Id, lastItem.CreatedAt) : null;

    return Results.Ok(new {
        data = items,
        pageInfo = new {
            hasNextPage,
            endCursor
        }
    });
});

