public async Task<PagedResult<OrderDto>> GetOrdersCursorAsync(string? cursor, int pageSize = 20)
{
    // MẸO VÀNG: Yêu cầu lấy pageSize + 1 (ví dụ 21 dòng thay vì 20)
    var query = _context.Orders.AsNoTracking();

    if (cursor != null)
    {
        var (lastDate, lastId) = DecodeCursor(cursor);
        query = query.Where(o => o.CreatedAt < lastDate || (o.CreatedAt == lastDate && o.Id < lastId));
    }

    var items = await query
        .OrderByDescending(o => o.CreatedAt)
        .ThenByDescending(o => o.Id)
        .Take(pageSize + 1)
        .ToListAsync();

    bool hasNextPage = items.Count > pageSize;
    if (hasNextPage)
    {
        items.RemoveAt(items.Count - 1); // Cắt bỏ phần tử thứ 21 thừa
    }

    string? nextCursor = hasNextPage ? EncodeCursor(items.Last()) : null;
    return new PagedResult<OrderDto>(items, hasNextPage, nextCursor);
}

