import { useInfiniteQuery } from '@tanstack/react-query';
import { useInView } from 'react-intersection-observer';
import { useEffect } from 'react';

// 1. Hàm gọi API phân trang theo Cursor
const fetchOrders = async ({ pageParam = null }) => {
  const url = pageParam 
    ? `/api/v1/orders?limit=20&cursor=${encodeURIComponent(pageParam)}`
    : '/api/v1/orders?limit=20';
  const res = await fetch(url);
  return res.json();
};

export function OrderInfiniteFeed() {
  const { ref, inView } = useInView();

  const {
    data,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
    status
  } = useInfiniteQuery({
    queryKey: ['orders-feed'],
    queryFn: fetchOrders,
    // Trích xuất endCursor từ backend trả về để làm tham số cho trang sau:
    getNextPageParam: (lastPage) => 
      lastPage.pageInfo.hasNextPage ? lastPage.pageInfo.endCursor : undefined,
  });

  // Tự động tải trang tiếp theo khi phần tử đáy màn hình xuất hiện trong Viewport
  useEffect(() => {
    if (inView && hasNextPage && !isFetchingNextPage) {
      fetchNextPage();
    }
  }, [inView, hasNextPage, isFetchingNextPage, fetchNextPage]);

  if (status === 'pending') return <div>Đang tải bảng tin...</div>;

  // Hợp nhất dữ liệu tất cả các trang
  const allOrders = data.pages.flatMap((page) => page.data);

  return (
    <div className="orders-feed">
      {allOrders.map((order) => (
        <div key={order.id} className="order-item">
          <h4>Đơn hàng #{order.id}</h4>
          <p>Khách hàng: {order.customerName} - {order.amount}$</p>
        </div>
      ))}

      {/* Trigger element nằm ở cuối danh sách */}
      <div ref={ref} className="loading-trigger">
        {isFetchingNextPage ? 'Đang tải thêm đơn hàng...' : hasNextPage ? 'Cuộn để tải thêm' : 'Đã tải hết đơn hàng!'}
      </div>
    </div>
  );
}

