public class CreateOrderHandler : IRequestHandler<CreateOrderCommand, OrderResult>
{
    private readonly IUserModuleApi _userModuleApi;
    private readonly IMediator _mediator;

    public CreateOrderHandler(IUserModuleApi userModuleApi, IMediator mediator)
    {
        _userModuleApi = userModuleApi;
        _mediator = mediator;
    }

    public async Task<OrderResult> Handle(CreateOrderCommand request, CancellationToken ct)
    {
        // 1. Gọi qua Interface công khai (In-memory, tốc độ nano-giây, 0 network latency!)
        var user = await _userModuleApi.GetUserSummaryAsync(request.UserId, ct);
        if (user == null) throw new NotFoundException("User not found");

        // 2. Tạo đơn hàng và bắn sự kiện In-Memory Event
        var order = new Order(request.UserId, request.Amount);
        await _mediator.Publish(new OrderPlacedDomainEvent(order.Id), ct);

        return new OrderResult(order.Id, "Success");
    }
}

