name: AI PR Review with Max 3 Rounds Cap

on:
  pull_request:
    types: [opened, synchronize]

jobs:
  check-review-count:
    runs-on: ubuntu-latest
    steps:
      - name: Count Previous AI Reviews
        id: count_reviews
        uses: actions/github-script@v7
        with:
          script: |
            const botName = 'github-actions[bot]';
            const reviews = await github.rest.pulls.listReviews({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.payload.pull_request.number,
            });

            // Đếm số lần bot đã review PR này
            const aiReviewCount = reviews.data.filter(r => r.user.login === botName).length;
            console.log(`Current AI review count: ${aiReviewCount}`);
            return aiReviewCount;

      - name: Execute AI Review (Vòng 1, 2 hoặc 3)
        if: steps.count_reviews.outputs.result < 3
        run: |
          echo "AI review round ${{ steps.count_reviews.outputs.result }} / 3 đang chạy..."
          # Kích hoạt Claude Code / Copilot API để review code diff

      - name: Fallback to Human Reviewer Handover (Khi chạm mốc 3 lần)
        if: steps.count_reviews.outputs.result >= 3
        uses: actions/github-script@v7
        with:
          script: |
            await github.rest.issues.addLabels({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.pull_request.number,
              labels: ['ai-review-cap-reached', 'needs-human-lead']
            });

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.payload.pull_request.number,
              body: '🛑 **AI Review Cap Reached (3/3 Rounds):**\nPR này đã qua 3 vòng review tự động. Để tránh vòng lặp nitpicking và trễ hạn, AI bot xin phép dừng lại. Mời @tech-lead vào review trực tiếp và đưa ra quyết định merge cuối cùng!'
            });

