// Cách Backend lấy Client IP chuẩn trong ASP.NET Core
public string GetClientCountry(HttpContext context, IGeoIPService geoService)
{
    // 1. Nếu đứng sau Cloudflare, đọc trực tiếp header do Edge gán
    if (context.Request.Headers.TryGetValue("CF-IPCountry", out var cfCountry))
    {
        return cfCountry.ToString(); // Trả về 'IN' nếu IP là Ấn Độ
    }

    // 2. Đọc Client IP từ X-Forwarded-For hoặc RemoteIpAddress
    var ipAddress = context.Connection.RemoteIpAddress?.ToString();

    // 3. Tra cứu trong MaxMind GeoLite2 Database
    var country = geoService.LookupCountry(ipAddress);
    return country; // "India"
}

