using System;
using System.Collections.Generic;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

public class CsvStreamBatchProcessor
{
    private const int BatchSize = 10_000; // 10.000 dòng mỗi đợt

    // Đọc file CSV theo từng dòng bằng luồng stream (Không bao giờ ReadAllLines)
    public async IAsyncEnumerable<TransactionRecord> ReadCsvStreamAsync(string filePath)
    {
        // Buffer 64KB tối ưu cho đĩa NVMe/SSD, không cấp phát mảng lớn
        using var fileStream = new FileStream(filePath, FileMode.Open, FileAccess.Read, 
            FileShare.Read, bufferSize: 64 * 1024, useAsync: true);
        using var reader = new StreamReader(fileStream);

        string? headerLine = await reader.ReadLineAsync(); // Bỏ qua header
        string? line;

        while ((line = await reader.ReadLineAsync()) != null)
        {
            if (string.IsNullOrWhiteSpace(line)) continue;
            yield return ParseCsvLine(line);
        }
    }

    // Xử lý gom batch và đẩy vào DB
    public async Task ProcessLargeFileAsync(string filePath, CancellationToken ct = default)
    {
        var batch = new List<TransactionRecord>(BatchSize);
        long totalProcessed = 0;

        await foreach (var record in ReadCsvStreamAsync(filePath).WithCancellation(ct))
        {
            batch.Add(record);

            if (batch.Count >= BatchSize)
            {
                await SaveBatchToDatabaseAsync(batch, ct);
                totalProcessed += batch.Count;
                batch.Clear(); // GIẢI PHÓNG BỘ NHỚ LẬP TỨC cho batch tiếp theo
            }
        }

        // Xử lý số lượng lẻ còn lại ở cuối file
        if (batch.Count > 0)
        {
            await SaveBatchToDatabaseAsync(batch, ct);
            totalProcessed += batch.Count;
            batch.Clear();
        }

        Console.WriteLine($"Đã xử lý thành công {totalProcessed:N0} dòng với RAM phẳng < 50 MB!");
    }

    private async Task SaveBatchToDatabaseAsync(List<TransactionRecord> batch, CancellationToken ct)
    {
        // Sử dụng Bulk Copy / SqlBulkCopy / PostgreSQL COPY để insert 10.000 dòng trong ~50ms
        await Task.Delay(20, ct); // Mô phỏng Bulk Insert
    }

    private TransactionRecord ParseCsvLine(string line)
    {
        var parts = line.Split(',');
        return new TransactionRecord(parts[0], decimal.Parse(parts[1]), DateTime.Parse(parts[2]));
    }
}

