using Amazon.S3;
using Amazon.S3.Model;
using System.IO;
using System.Threading.Tasks;

public class S3ChunkDownloader
{
    private readonly IAmazonS3 _s3Client;

    public S3ChunkDownloader(IAmazonS3 s3Client) => _s3Client = s3Client;

    // Đọc chính xác 50 MB phân đoạn từ file 5 GB trên S3 mà không cần tải toàn bộ
    public async Task<Stream> GetChunkStreamAsync(string bucket, string key, long startByte, long endByte)
    {
        var request = new GetObjectRequest
        {
            BucketName = bucket,
            Key = key,
            ByteRange = new ByteRange(startByte, endByte) // Header: Range: bytes=0-52428800
        };

        GetObjectResponse response = await _s3Client.GetObjectAsync(request);
        return response.ResponseStream;
    }
}

