}

using System.Collections.Generic;
using System.Threading.Channels;
using System.Threading.Tasks;

public class BoundedPipelineService
{
    public async Task RunPipelineAsync()
    {
        // Chỉ cho phép tối đa 10 batch (mỗi batch 10.000 dòng) nằm trong RAM
        var options = new BoundedChannelOptions(capacity: 10)
        {
            FullMode = BoundedChannelFullMode.Wait, // Khi đầy, Writer sẽ chờ (Backpressure)
            SingleWriter = true,
            SingleReader = false // Cho phép nhiều Worker consumer đọc song song
        };

        var channel = Channel.CreateBounded<List<TransactionRecord>>(options);

        // Khởi chạy Producer đọc file
        var producerTask = Task.Run(() => ProduceBatchesAsync(channel.Writer));

        // Khởi chạy 3 Worker Consumer song song
        var consumerTasks = new List<Task>();
        for (int i = 0; i < 3; i++)
        {
            int workerId = i + 1;
            consumerTasks.Add(Task.Run(() => ConsumeBatchesAsync(workerId, channel.Reader)));
        }

        await producerTask;
        await Task.WhenAll(consumerTasks);
    }

    private async Task ProduceBatchesAsync(ChannelWriter<List<TransactionRecord>> writer)
    {
        // Đọc stream và gom batch...
        // writer.WriteAsync(batch) sẽ tạm hoãn nếu channel đang chứa đủ 10 batch
        writer.Complete();
    }

    private async Task ConsumeBatchesAsync(int workerId, ChannelReader<List<TransactionRecord>> reader)
    {
        await foreach (var batch in reader.ReadAllAsync())
        {
            // Bulk insert vào database
            batch.Clear();
        }
    }
}

