-- 2. Giao dịch kiểm tra và trừ chỗ trống an toàn tuyệt đối với UPDLOCK
CREATE OR ALTER PROCEDURE dbo.usp_RegisterStudentToClass
    @ClassId INT,
    @StudentId INT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON; -- Tự động rollback toàn bộ nếu có bất kỳ lỗi runtime nào

    BEGIN TRANSACTION;

    DECLARE @CurrentCount INT, @MaxCapacity INT;

    -- Giữ khóa Update trên đúng dòng ClassId này ngay từ lúc đọc để chặn các luồng song song
    SELECT @CurrentCount = CurrentEnrolled, @MaxCapacity = MaxCapacity
    FROM dbo.Classes WITH (UPDLOCK, ROWLOCK)
    WHERE ClassId = @ClassId;

    IF (@CurrentCount >= @MaxCapacity)
    BEGIN
        ROLLBACK TRANSACTION;
        THROW 50001, N'Lớp học đã đủ sĩ số tối đa.', 1;
    END

    INSERT INTO dbo.Enrollments (ClassId, StudentId, EnrolledAt)
    VALUES (@ClassId, @StudentId, SYSUTCDATETIME());

    UPDATE dbo.Classes
    SET CurrentEnrolled = CurrentEnrolled + 1
    WHERE ClassId = @ClassId;

    COMMIT TRANSACTION;
END;

