public class EnterpriseClaimsTransformation : IClaimsTransformation
{
    private readonly IPermissionCacheService _permCache;
    public EnterpriseClaimsTransformation(IPermissionCacheService permCache) => _permCache = permCache;

    public async Task<ClaimsPrincipal> TransformAsync(ClaimsPrincipal principal)
    {
        var clone = principal.Clone();
        var newIdentity = (ClaimsIdentity)clone.Identity!;

        var oktaUserId = principal.FindFirstValue(ClaimTypes.NameIdentifier) ?? principal.FindFirstValue("sub");
        if (!string.IsNullOrEmpty(oktaUserId))
        {
            var permissions = await _permCache.GetUserPermissionsAsync(oktaUserId);
            foreach (var perm in permissions)
            {
                newIdentity.AddClaim(new Claim("permission", perm));
            }
        }
        return clone;
    }
}

