public async Task<AuthResult> RotateRefreshTokenAsync(string rawRefreshToken, string ipAddress)
{
    var hashedToken = HashToken(rawRefreshToken);
    var tokenRecord = await _db.RefreshTokens.FirstOrDefaultAsync(t => t.TokenHash == hashedToken);

    if (tokenRecord == null)
        throw new SecurityTokenException("Refresh token không tồn tại.");

    // PHÁT HIỆN TÁI SỬ DỤNG: Token này đã bị thu hồi trước đó nhưng lại được dùng lại!
    if (tokenRecord.IsRevoked)
    {
        // Thu hồi toàn bộ dòng họ Token (Token Family) để khóa kẻ gian
        await RevokeEntireFamilyAsync(tokenRecord.FamilyId, "Phát hiện tấn công Replay Attack");
        throw new SecurityTokenException("Phát hiện truy cập bất thường. Tất cả phiên đăng nhập đã bị hủy!");
    }

    tokenRecord.IsRevoked = true;
    tokenRecord.RevokedAt = DateTime.UtcNow;

    var newRefreshToken = GenerateSecureRandomToken();
    var newRecord = new RefreshTokenRecord
    {
        FamilyId = tokenRecord.FamilyId,
        UserId = tokenRecord.UserId,
        TokenHash = HashToken(newRefreshToken),
        ExpiresAt = DateTime.UtcNow.AddDays(7),
        CreatedByIp = ipAddress
    };

    _db.RefreshTokens.Add(newRecord);
    await _db.SaveChangesAsync();

    var newAccessToken = _jwtService.GenerateAccessToken(tokenRecord.UserId);
    return new AuthResult(newAccessToken, newRefreshToken);
}

public void AppendAuthCookies(HttpResponse response, string accessToken, string refreshToken)
{
    var cookieOptions = new CookieOptions
    {
