public class IdempotencyFilter : IEndpointFilter
{
    private readonly IDatabase _redis;
    public IdempotencyFilter(IConnectionMultiplexer mux) => _redis = mux.GetDatabase();

    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext ctx, EndpointFilterDelegate next)
    {
        var httpContext = ctx.HttpContext;
        if (!httpContext.Request.Headers.TryGetValue("Idempotency-Key", out var keyHeader) ||
            string.IsNullOrWhiteSpace(keyHeader))
        {
            return Results.BadRequest(new { error = "Missing required Idempotency-Key header" });
        }

        string key = $"idempotency:{keyHeader}";
        string lockKey = $"lock:{key}";
        string fingerprint = await ComputeBodyHashAsync(httpContext.Request);

        // 1. Kiểm tra xem key đã hoàn thành chưa
        var existing = await _redis.StringGetAsync(key);
        if (!existing.IsNullOrEmpty)
        {
            var cached = JsonSerializer.Deserialize<CachedResponse>(existing!);
            if (cached!.Fingerprint != fingerprint)
            {
                return Results.Problem("Idempotency key reused with different parameters", statusCode: 422);
            }
            httpContext.Response.Headers.Append("X-Cache-Lookup", "HIT-IDEMPOTENT");
            return Results.Content(cached.Body, "application/json", statusCode: cached.StatusCode);
        }

        // 2. Thử lấy lock phân tán trong 30 giây (tránh race condition song song)
        bool lockAcquired = await _redis.StringSetAsync(lockKey, "locked", TimeSpan.FromSeconds(30), When.NotExists);
        if (!lockAcquired)
        {
            return Results.Problem("A request with this idempotency key is currently being processed", statusCode: 409);
        }

        try
        {
            var result = await next(ctx);
            if (result is IStatusCodeHttpResult statusResult && result is IValueHttpResult valueResult)
            {
                int statusCode = statusResult.StatusCode ?? 200;
                var toCache = new CachedResponse
                {
                    Fingerprint = fingerprint,
                    StatusCode = statusCode,
                    Body = JsonSerializer.Serialize(valueResult.Value)
                };
                await _redis.StringSetAsync(key, JsonSerializer.Serialize(toCache), TimeSpan.FromHours(24));
            }
            return result;
        }
        finally
        {
            await _redis.KeyDeleteAsync(lockKey);
        }
    }

    private static async Task<string> ComputeBodyHashAsync(HttpRequest request)
    {
        request.EnableBuffering();
        using var reader = new StreamReader(request.Body, Encoding.UTF8, leaveOpen: true);
        string body = await reader.ReadToEndAsync();
        request.Body.Position = 0; // Tua lại stream về 0 cho Controller đọc
        byte[] hash = SHA256.HashData(Encoding.UTF8.GetBytes($"{request.Method}:{request.Path}:{body}"));
        return Convert.ToHexString(hash);
    }
}

[HttpPost("webhooks/stripe")]
public async Task<IActionResult> HandleStripeWebhook()
{
    var json = await new StreamReader(HttpContext.Request.Body).ReadToEndAsync();
    var stripeEvent = EventUtility.ConstructEvent(json, Request.Headers["Stripe-Signature"], _webhookSecret);

    // 1. Kiểm tra xem event này đã xử lý chưa
    bool alreadyProcessed = await _db.ConsumedWebhooks.AnyAsync(w => w.EventId == stripeEvent.Id);
    if (alreadyProcessed)
    {
        // Trả về 200 OK ngay lập tức để Stripe dừng gửi lại
        return Ok(new { message = "Event already acknowledged" });
    }

    // 2. Xử lý sự kiện và lưu eventId trong cùng 1 Database Transaction
    using var tx = await _db.Database.BeginTransactionAsync();
    if (stripeEvent.Type == Events.PaymentIntentSucceeded)
    {
        var paymentIntent = stripeEvent.Data.Object as PaymentIntent;
        await FulfillOrderAsync(paymentIntent!.Metadata["order_id"]);
    }

    _db.ConsumedWebhooks.Add(new ConsumedWebhook { EventId = stripeEvent.Id, HandledAt = DateTime.UtcNow });
    await _db.SaveChangesAsync();
    await tx.CommitAsync();

    return Ok();
}

