public static class TokenService
{
    public static string GenerateJwt(string userId, string email, string role, string secretKey)
    {
        var handler = new JsonWebTokenHandler();
        var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey));
        var credentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

        var tokenDescriptor = new SecurityTokenDescriptor
        {
            Issuer = "https://auth.mycompany.com",
            Audience = "https://api.mycompany.com",
            Subject = new ClaimsIdentity(new[]
            {
                new Claim(JwtRegisteredClaimNames.Sub, userId),
                new Claim(JwtRegisteredClaimNames.Email, email),
                new Claim(ClaimTypes.Role, role),
                new Claim(JwtRegisteredClaimNames.Jti, Guid.NewGuid().ToString())
            }),
            Expires = DateTime.UtcNow.AddMinutes(30),
            SigningCredentials = credentials
        };

        return handler.CreateToken(tokenDescriptor);
    }
}

public static async Task<TokenValidationResult> ValidateJwtAsync(string token, string secretKey)
{
    var handler = new JsonWebTokenHandler();
    var validationParameters = new TokenValidationParameters
    {
        ValidateIssuer = true,
        ValidIssuer = "https://auth.mycompany.com",

        ValidateAudience = true,
        ValidAudience = "https://api.mycompany.com",

        ValidateIssuerSigningKey = true,
        IssuerSigningKey = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(secretKey)),

        ValidateLifetime = true,
        ClockSkew = TimeSpan.Zero //  Bắt buộc đặt ClockSkew = Zero để hết hạn chuẩn xác!
    };

    return await handler.ValidateTokenAsync(token, validationParameters);
}

