public class OrderProcessingBackgroundService : BackgroundService
{
    // Inject IServiceScopeFactory thay vì inject trực tiếp DbContext
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<OrderProcessingBackgroundService> _logger;

    public OrderProcessingBackgroundService(IServiceScopeFactory scopeFactory, ILogger<OrderProcessingBackgroundService> logger)
    {
        _scopeFactory = scopeFactory;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            // Mở scope thủ công cho mỗi chu kỳ làm việc
            using (var scope = _scopeFactory.CreateScope())
            {
                var dbContext = scope.ServiceProvider.GetRequiredService<AppDbContext>();
                var pendingOrders = await dbContext.Orders.Where(o => o.Status == OrderStatus.Pending).ToListAsync(stoppingToken);

                // Xử lý đơn hàng an toàn, khi hết scope using dbContext sẽ được giải phóng lập tức
            }

            await Task.Delay(TimeSpan.FromSeconds(30), stoppingToken);
        }
    }
}

public async Task<List<OrderDetailDto>> GetRecentOrdersAsync(int customerId, CancellationToken ct)
{
    return await _context.Orders
        .AsNoTracking()
        .Where(o => o.CustomerId == customerId)
        .OrderByDescending(o => o.CreatedAt)
        .Take(20)
        // Dùng AsSplitQuery khi materialize nhiều collection con để tránh Cartesian Explosion
        .AsSplitQuery()
        .Select(o => new OrderDetailDto
        {
            OrderId = o.Id,
            OrderDate = o.CreatedAt,
            TotalAmount = o.TotalAmount,
            Items = o.Items.Select(i => new OrderItemDto(i.ProductId, i.Quantity)).ToList(),
            Payments = o.PaymentLogs.Select(p => new PaymentLogDto(p.TransactionId, p.Status)).ToList()
        })
        .ToListAsync(ct);
}

