    private readonly HybridCache _cache;
    private readonly AppDbContext _db;

    public ProductService(HybridCache cache, AppDbContext db)
    {
        _cache = cache;
        _db = db;
    }

    public async Task<ProductDto?> GetProductByIdAsync(int id, CancellationToken ct)
    {
        string key = $"product:{id}";
        return await _cache.GetOrCreateAsync(key, async cancelToken =>
        {
            var entity = await _db.Products.FindAsync([id], cancelToken);
            return entity is null ? null : new ProductDto(entity.Id, entity.Name, entity.Price);
        },
        tags: ["products", $"product-category-{id}"],
        cancellationToken: ct);
    }

    public async Task InvalidateProductCacheAsync(int id)
    {
        // Xóa cache theo key hoặc tag nhóm cực kỳ tiện lợi
        await _cache.RemoveByTagAsync($"product-category-{id}");
    }
}

public class AuditLogQueue
{
    private readonly Channel<AuditLogMessage> _channel;

    public AuditLogQueue()
    {
        // Giới hạn 5.000 phần tử, nếu đầy thì Producer sẽ chờ async (Backpressure)
        var options = new BoundedChannelOptions(5000)
        {
            FullMode = BoundedChannelFullMode.Wait,
            SingleReader = true,
            SingleWriter = false
        };
        _channel = Channel.CreateBounded<AuditLogMessage>(options);
    }

    public ValueTask EnqueueAsync(AuditLogMessage msg, CancellationToken ct = default)
        => _channel.Writer.WriteAsync(msg, ct);

    public IAsyncEnumerable<AuditLogMessage> ReadAllAsync(CancellationToken ct = default)
        => _channel.Reader.ReadAllAsync(ct);
}

public class OrderSubmittedConsumer : IConsumer<OrderSubmittedEvent>
{
    private readonly ILogger<OrderSubmittedConsumer> _logger;

    public OrderSubmittedConsumer(ILogger<OrderSubmittedConsumer> logger)
    {
        _logger = logger;
    }

    public async Task Consume(ConsumeContext<OrderSubmittedEvent> context)
    {
        var message = context.Message;
        _logger.LogInformation("Bắt đầu xử lý đơn hàng: {OrderId}", message.OrderId);

        // Thực thi logic trừ tiền và xuất hóa đơn...
        await Task.CompletedTask;
    }
}

// Đăng ký trong Program.cs với Retry Policy
builder.Services.AddMassTransit(x =>
{
    x.AddConsumer<OrderSubmittedConsumer>();
    x.UsingRabbitMq((ctx, cfg) =>
    {
        cfg.Host("rabbitmq://localhost");
        cfg.UseMessageRetry(r => r.Exponential(3, TimeSpan.FromSeconds(1), TimeSpan.FromSeconds(10), TimeSpan.FromSeconds(2)));
        cfg.ConfigureEndpoints(ctx);
    });
});

